// Embeds the SQL files generated by drizzle-kit (./drizzle/*.sql) into a TypeScript module so
// migrations run automatically on serverless hosts (Vercel) without needing file-system access.
// Run via: npm run db:generate
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(process.cwd(), "drizzle");
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const migrations = files.map((f) => ({ name: f.replace(/\.sql$/, ""), sql: readFileSync(join(dir, f), "utf8") }));
const out = `// AUTO-GENERATED by scripts/embed-migrations.mjs - do not edit by hand.\n// Source: ./drizzle/*.sql (generated by drizzle-kit from src/server/db/schema.ts)\nexport const MIGRATIONS: { name: string; sql: string }[] = ${JSON.stringify(migrations, null, 2)};\n`;
writeFileSync(join(process.cwd(), "src/server/db/migrations.ts"), out);
console.log(`Embedded ${migrations.length} migration(s): ${migrations.map((m) => m.name).join(", ")}`);
